import { reactionClock } from './components.js';
import { prepareStudio } from './studio.js';
export const demonstrations = [
 {id:'light',title:'發光與放熱',name:'鎂帶燃燒',before:'銀白色鎂帶，由坩堝鉗夾持在酒精燈上方。',during:'鎂帶燃燒，發出白光，並放出熱量。',after:'留下白色氧化鎂；這是與原來鎂帶不同的物質。',equation:'2Mg + O₂ → 2MgO',action:'點火，觀察鎂帶',product:'白色氧化鎂',note:'以柔和光暈代替實際強光；真實實驗勿直視燃燒的鎂。'},
 {id:'color',title:'顏色改變',name:'五水硫酸銅受熱',before:'蒸發皿內有藍色的五水硫酸銅晶體。',during:'持續加熱，晶體逐漸失去結晶水，藍色轉淡。',after:'留下白色的無水硫酸銅，水以水蒸氣離開。',equation:'CuSO₄·5H₂O → CuSO₄ + 5H₂O',action:'加熱，觀察顏色',product:'白色無水硫酸銅',note:'反應條件：加熱。以淡色軌跡標示水蒸氣去向；水蒸氣本身無色。'},
 {id:'solid',title:'生成沉澱',name:'碳酸鈉溶液＋氯化鈣溶液',before:'兩種溶液原本都透明，還沒有接觸。',during:'倒入氯化鈣溶液，混合處逐漸出現白色混濁。',after:'生成不溶於水的碳酸鈣，白色固體逐漸沉降。',equation:'Na₂CO₃ + CaCl₂ → CaCO₃↓ + 2NaCl',action:'混合，觀察沉澱',product:'白色碳酸鈣沉澱',note:'沉降過程經過加速。CaCO₃ 是固體，NaCl 仍溶在水中。'},
 {id:'gas',title:'產生氣體',name:'石灰石＋稀鹽酸',before:'燒杯內是石灰石與少量水；滴管內是稀鹽酸。',during:'酸滴到石灰石，固體表面出現持續上升的氣泡。',after:'生成的二氧化碳離開液面；石灰石逐漸減少。',equation:'CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂↑',action:'滴入，觀察氣泡',product:'二氧化碳氣體',note:'石灰石示意為過量，反應後仍有剩餘；氣體身分需另行檢驗。'}
];
export function phenomenonScene(id,p=0){
 const k=Math.min(1,Math.max(0,p)),active=k>0&&k<1,change=Math.min(1,k*1.6),prefix='ph-'+id;
 const text=(x,y,t,size=14)=>'<text x="'+x+'" y="'+y+'" text-anchor="middle" fill="#527269" font-size="'+size+'">'+t+'</text>';
 const glass='url(#'+prefix+'-glass)',metal='url(#'+prefix+'-metal)';
 const lamp='<g><ellipse cx="340" cy="342" rx="46" ry="8" fill="#18382e" opacity=".15"/><path d="M310 289Q294 302 301 331Q340 348 379 331Q386 302 370 289Z" fill="'+glass+'" stroke="#729e99" stroke-width="2"/><path d="M305 316Q340 306 375 316V330Q340 343 305 330Z" fill="#c5d9d0"/><ellipse cx="340" cy="290" rx="30" ry="7" fill="'+metal+'"/><path d="M334 290v-15h12v15" fill="#dac6a0"/>'+(active?'<path d="M340 279Q313 263 340 229Q367 263 340 279" fill="#e9a951" opacity=".85"/><path d="M340 279Q328 268 340 251Q352 268 340 279" fill="#76c5d8"/>':'')+'</g>';
 const beaker='<path d="M272 190H405L397 200V321Q337 342 280 321V200Z" fill="'+glass+'" stroke="#719b96" stroke-width="2"/><path d="M286 211V312" stroke="#fff" stroke-width="5" opacity=".8"/>'+[230,253,276].map((y,i)=>'<path d="M374 '+y+'h16" stroke="#739c93"/>'+text(365,y+4,100-i*25,9)).join('');
 let body='';
 if(id==='light')body=lamp+'<ellipse cx="490" cy="333" rx="62" ry="13" fill="#cbd6d0"/><path d="M428 324Q490 365 552 324" fill="#fffdf4" stroke="#9cae9f" stroke-width="2"/><ellipse cx="490" cy="324" rx="62" ry="11" fill="#f8f8ef" stroke="#afbcaf"/><path d="M487 322l12 -2 10 5 -24 1Z" fill="#fff" opacity="'+k+'"/><path d="M535 113L350 204M535 126L347 208" stroke="'+metal+'" stroke-width="7" stroke-linecap="round"/><circle cx="491" cy="137" r="4" fill="#869b95"/><path d="M348 207l-17 9 18 10 -12 9" fill="none" stroke="'+(k>.6?'#f8fbef':'#b0bdc1')+'" stroke-width="5"/>'+(active?'<circle cx="340" cy="220" r="'+(15+Math.sin(k*8)*3)+'" fill="url(#'+prefix+'-glow)"/><circle cx="340" cy="220" r="5" fill="#fffef0"/>':'')+text(510,93,'坩堝鉗')+text(490,380,'瓷皿收集生成物')+text(340,380,'酒精燈')+text(218,204,k>.6?'白色氧化鎂':'鎂帶');
 if(id==='color')body=lamp+'<path d="M261 221L243 343M419 221L437 343M340 221V340" stroke="'+metal+'" stroke-width="6"/><ellipse cx="340" cy="220" rx="81" ry="12" fill="none" stroke="#758b83" stroke-width="7"/><path d="M263 201Q340 252 417 201" fill="#e6e9e0" stroke="#8fa69b" stroke-width="2"/><ellipse cx="340" cy="201" rx="77" ry="15" fill="#f8faf1" stroke="#9daf9f"/>'+Array.from({length:24},(_,i)=>'<path d="M'+(292+i*23%91)+' '+(193+i*7%17)+'l8 -4 6 5 -9 5Z" fill="'+(k>i/26?'#f9faf1':'#399bc4')+'" stroke="'+(k>i/26?'#d6dfd3':'#277897')+'"/>').join('')+(active?Array.from({length:4},(_,i)=>'<path d="M'+(300+i*26)+' 175q-12 -18 0 -30t0 -30" fill="none" stroke="#a5c2b6" opacity="'+(.2+(k+i*.2)%0.5)+'" stroke-width="2"/>').join(''):'')+text(525,200,k>.6?'藍色 → 白色':'藍色晶體')+text(340,380,'蒸發皿 · 三腳架 · 酒精燈');
 if(id==='solid')body='<g transform="rotate('+(-Math.min(1,k*6)*48*(k<.35?1:Math.max(0,(.55-k)/.2)))+' 417 120)"><path d="M414 69H481V136Q449 151 419 136V80Z" fill="'+glass+'" stroke="#719b96" stroke-width="2"/><path d="M422 104H476V133Q449 144 422 133Z" fill="#d9ece4" opacity="'+(1-change*.8)+'"/></g>'+text(500,62,'氯化鈣溶液')+(k>0&&k<.4?'<path d="M414 128Q363 155 345 251" fill="none" stroke="#c8e3db" stroke-width="6"/>':'')+'<path d="M280 252Q340 244 397 252V321Q340 338 280 321Z" fill="#daebe4"/><ellipse cx="339" cy="252" rx="58" ry="7" fill="#e8f2ec"/>'+ '<path d="M281 258Q320 235 349 264T397 255V321Q340 338 281 321Z" fill="#fffef4" opacity="'+change*.85+'"/>'+Array.from({length:35},(_,i)=>'<circle cx="'+(287+i*17%104)+'" cy="'+(265+i*11%52+Math.max(0,k-.5)*16)+'" r="2" fill="#fff" opacity="'+change+'"/>').join('')+'<path d="M281 316Q340 '+(321-change*24)+' 397 316V321Q340 338 281 321Z" fill="#fffdf1" opacity="'+change+'"/>'+beaker+text(338,380,'碳酸鈉溶液')+text(531,282,k>.2?'白色碳酸鈣沉澱':'兩種透明溶液');
 if(id==='gas')body='<path d="M341 73V146l-5 10 -5 -10V73" fill="'+glass+'" stroke="#83aaa1" stroke-width="2"/><rect x="325" y="45" width="22" height="45" rx="10" fill="#a65f4a"/>'+text(449,103,'稀鹽酸')+(k>0&&k<.45?'<path d="M336 '+(165+k*120%45)+'q-8 12 0 13q8 -1 0 -13" fill="#bcdbd6"/>':'')+'<path d="M280 261Q339 253 397 261V321Q340 338 280 321Z" fill="#dfede5"/>'+[0,1,2,3].map(i=>'<path d="M'+(298+i*22)+' 310l8 -'+(13-k*7)+' 12 5 -3 12 -15 2Z" fill="#cdc6b2" stroke="#9fa694"/>').join('')+(active?Array.from({length:19},(_,i)=>'<circle cx="'+(292+i*31%94)+'" cy="'+(313-(k*260+i*17)%57)+'" r="'+(2+i%3)+'" fill="#fff" fill-opacity=".6" stroke="#89b5ab"/>').join(''):'')+beaker+text(338,380,'石灰石')+text(528,265,k>0?'氣泡：二氧化碳':'觀察固體表面');
 return '<svg viewBox="0 0 760 410" role="img" aria-label="'+demonstrations.find(d=>d.id===id).name+'：'+(k===0?'反應前':k===1?'反應後':'反應中')+'"><defs><linearGradient id="'+prefix+'-glass"><stop stop-color="#8eb8b0" stop-opacity=".38"/><stop offset=".18" stop-color="#fff" stop-opacity=".75"/><stop offset=".5" stop-color="#e5f2eb" stop-opacity=".12"/><stop offset="1" stop-color="#a6c9bf" stop-opacity=".5"/></linearGradient><linearGradient id="'+prefix+'-metal"><stop stop-color="#536e66"/><stop offset=".45" stop-color="#f4f8f0"/><stop offset="1" stop-color="#78968c"/></linearGradient><radialGradient id="'+prefix+'-glow"><stop stop-color="#fffef4"/><stop offset=".3" stop-color="#fff6bd" stop-opacity=".9"/><stop offset="1" stop-color="#f9dc8b" stop-opacity="0"/></radialGradient><linearGradient id="'+prefix+'-wall" x2="0" y2="1"><stop stop-color="#f0f4ed"/><stop offset="1" stop-color="#dce6de"/></linearGradient></defs><rect width="760" height="410" fill="url(#'+prefix+'-wall)"/><path d="M0 90H760M0 180H760M190 0V290M570 0V290" stroke="#fff" opacity=".5"/><path d="M0 290H760V410H0Z" fill="#cedbd1"/><path d="M0 291H760" stroke="#f9fff5" stroke-width="3"/><ellipse cx="360" cy="344" rx="188" ry="16" fill="#446d5c" opacity=".1"/>'+body+'</svg>';
}
export function mountPhenomena(root,ctx){
 let selected=0,p=0,running=false;const seen=new Set();
 root.classList.add('phenomena-studio');root.setAttribute('data-glossary-skip','');
 root.innerHTML='<div class="phenomena-tabs" role="group" aria-label="選擇反應示範">'+demonstrations.map((d,i)=>'<button data-demo="'+i+'" aria-pressed="'+(i===0)+'"><span>0'+(i+1)+'</span><b>'+d.title+'</b><small>'+d.name+'</small></button>').join('')+'</div><div class="reaction-theater"><div class="reaction-stage"><div class="reaction-stage-head"><span>實例觀察 / 教學動畫</span><b class="reaction-phase"></b></div><div class="reaction-art"></div><progress max="1" value="0" aria-label="反應示範進度"></progress></div><aside class="reaction-notes"><span class="studio-eyebrow">觀察一個真實反應的過程</span><h3 class="reaction-name"></h3><div class="reaction-observation" role="status"></div><div class="reaction-equation"></div><button class="primary demonstrate"></button><button class="text-button reaction-rewind">回到反應前</button></aside></div><p class="reaction-note"></p><div class="evidence-caution"><b>看到變化，還要確認是否生成新物質。</b><p>水沸騰也會冒泡，卻仍是 H₂O。這些動畫重現實驗現象，並非實拍；速度與外觀經過簡化。真實實驗需由教師指導。</p></div>';
 prepareStudio(root,{number:'02',title:'化學反應觀察室',description:'選一個實例，按下反應，觀察材料如何改變。'}, {predict:()=>true});
 function draw(){const d=demonstrations[selected],phase=p===0?'反應前':p===1?'反應後':running?'反應中':'已暫停';root.querySelector('.reaction-art').innerHTML=phenomenonScene(d.id,p);root.querySelector('.reaction-phase').textContent=phase;root.querySelector('progress').value=p;root.querySelector('.reaction-name').textContent=d.name;const observation='<span>'+phase+'</span><p>'+(p===0?d.before:p===1?d.after:d.during)+'</p>'+(p===1?'<b>新物質：'+d.product+'</b>':'');if(root.querySelector('.reaction-observation').innerHTML!==observation)root.querySelector('.reaction-observation').innerHTML=observation;root.querySelector('.reaction-equation').textContent=d.equation;root.querySelector('.reaction-note').textContent=d.note;root.querySelector('.demonstrate').textContent=running?'Ⅱ 暫停觀察':p===1?'↻ 再反應一次':p>0?'▶ 繼續觀察':'▶ 反應 · '+d.action;root.querySelectorAll('[data-demo]').forEach(b=>{b.setAttribute('aria-pressed',String(+b.dataset.demo===selected));b.classList.toggle('has-observed',seen.has(+b.dataset.demo));});}
 const clock=reactionClock((value,run)=>{p=value;running=run;draw();},()=>{seen.add(selected);ctx.mark();draw();});
 root.querySelector('.demonstrate').onclick=()=>{if(running)clock.pause();else{if(p===1)clock.reset();running=true;draw();clock.start();}};
 root.querySelector('.reaction-rewind').onclick=()=>clock.reset();root.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>{clock.pause();selected=+b.dataset.demo;clock.reset();});draw();return{reset(){seen.clear();selected=0;clock.reset();}};
}
